window.ENEM_RESOLUTION_CHUNKS=window.ENEM_RESOLUTION_CHUNKS||{};window.ENEM_RESOLUTION_CHUNKS["data/resolucoes/linguagens_2021.js"]=[{"title":"O culto depende também da adesão dos fãs","steps":["O texto descreve fabricação comercial de imagens.","Depois desloca a responsabilidade: a sociedade aceita ideias sem questionar.","C resume o convite à reflexão autônoma do público."],"alternatives":{"A":"O texto questiona os critérios de fama, não enumera méritos.","B":"O consumo criticado é sobretudo o dos seguidores, não o das celebridades.","C":"Pensar por si e questionar a influência é a conclusão argumentativa.","D":"O autor afirma que celebridades não podem ser culpadas por tudo.","E":"O marketing é desvelado criticamente, não celebrado como valor."},"takeaway":"Leia o desfecho: a tese pode deslocar o foco do exemplo inicial.","key":"linguagens:L507","area":"linguagens","year":2021,"number":1,"answer":"C","subject":"Inglês","topic":"Interpretação de textos em língua inglesa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[2,4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A receita representa uma sociedade plural","steps":["Verbos como add, stir e serve imitam instruções culinárias.","Povos e línguas funcionam como ingredientes igualmente importantes.","A identifica valorização da mistura cultural, acompanhada de justiça e igualdade."],"alternatives":{"A":"A combinação de povos é enriquecida pelo respeito igual a cada componente.","B":"Não se explica apenas uma herança de uma localização geográfica.","C":"A história é matéria do poema, mas o efeito da receita é valorizar a composição plural.","D":"Desigualdade aparece como advertência, não como centro exclusivo da formação descrita.","E":"O poema pede que línguas floresçam, não relata apenas intolerância linguística."},"takeaway":"Reconhecer o gênero emprestado ajuda a interpretar a metáfora de um texto.","key":"linguagens:L508","area":"linguagens","year":2021,"number":2,"answer":"A","subject":"Inglês","topic":"Interpretação de textos em língua inglesa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[2,4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Impensável expressa a barreira racial à ascensão","steps":["O texto descreve negação de tratamento respeitoso a mulheres negras.","Contrapõe esse passado à possibilidade de uma mulher negra ser primeira-dama.","A identifica a ascensão antes considerada improvável pelo racismo."],"alternatives":{"A":"O cargo contrasta com a subordinação social imposta às mulheres negras.","B":"Dar à filha o nome Miss foi uma estratégia efetivamente realizada.","C":"A origem racial é decisiva no quadro de discriminação narrado.","D":"O trabalho feminino existia, mas era restringido a posições subordinadas.","E":"O texto apresenta resistência dos pais, não sua irresponsabilidade."},"takeaway":"Identifique o referente de uma avaliação: unthinkable qualifica a posição de primeira-dama nesse contexto.","key":"linguagens:L509","area":"linguagens","year":2021,"number":3,"answer":"A","subject":"Inglês","topic":"Interpretação de textos em língua inglesa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[3,5],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Estar informado entra em conflito com preservar a tranquilidade","steps":["A personagem quer estar bem informada e permanecer sã.","At odds with indica conflito entre esses dois desejos.","B identifica dificuldade de conciliá-los, no humor sobre notícias perturbadoras."],"alternatives":{"A":"A frase não discute diretamente escolher fontes confiáveis.","B":"Os dois anseios aparecem como incompatíveis diante do noticiário.","C":"Não há objetivo de aprender a operar novas tecnologias.","D":"A tensão não é entre opiniões políticas e imparcialidade.","E":"Querer notícias boas seria outra ideia; a fala confronta informação e bem-estar."},"takeaway":"Interprete expressões idiomáticas pela relação entre as duas partes da fala.","key":"linguagens:L510","area":"linguagens","year":2021,"number":4,"answer":"B","subject":"Inglês","topic":"Interpretação de textos em língua inglesa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[3,5],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O visitante constrói a avaliação do lugar","steps":["Jesse sugere feiura; Celine prefere falar em neutralidade.","A história europeia pode ser bela e, para ela, opressiva.","B reconhece que o julgamento depende da perspectiva de quem visita."],"alternatives":{"A":"A beleza não determina uma avaliação única: pode até oprimir.","B":"Os personagens atribuem sentidos distintos às características do lugar.","C":"Contexto histórico contribui, mas não fixa sozinho a avaliação.","D":"O diálogo não estabelece a duração como critério decisivo.","E":"Lua de mel é um exemplo na argumentação, não a única condição do julgamento."},"takeaway":"Uma característica do espaço pode receber avaliações diferentes segundo experiências e expectativas.","key":"linguagens:L511","area":"linguagens","year":2021,"number":5,"answer":"B","subject":"Inglês","topic":"Interpretação de textos em língua inglesa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[3,5],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A hipótese transforma o desvio em cenário de catástrofe","steps":["O asteroide não colidiu com a Terra.","Sequências com se imaginam captura, impacto continental e queda oceânica.","B identifica a repetição de hipóteses destrutivas como estratégia alarmante."],"alternatives":{"A":"A velocidade é um dado, mas não organiza todos os cenários de destruição.","B":"Os condicionais acumulam consequências catastróficas de algo que não ocorreu.","C":"A atribuição à Nasa dá credibilidade, não explica por si o tom alarmante.","D":"A locução intensifica uma estimativa, mas não resume a estratégia repetida.","E":"A distância contextualiza a passagem, sem produzir todos os cenários hipotéticos."},"takeaway":"Distinga acontecimento noticiado de consequência apenas possível ou contrafactual.","key":"linguagens:L341","area":"linguagens","year":2021,"number":6,"answer":"B","subject":"Gramática a serviço do sentido","topic":"Classes de palavras, referenciação e efeitos de sentido","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[6],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O uso popular também constitui a língua","steps":["O poeta ironiza substituir pega por captura para parecer correto.","Propõe registrar expressões que o povo já usa.","D valoriza variedades populares como fonte legítima do patrimônio linguístico."],"alternatives":{"A":"O contraste não se reduz à oposição entre falar e escrever.","B":"A ironia atinge o preciosismo do literato, não a fala popular.","C":"A substituição formal é criticada, e não recomendada.","D":"As expressões populares merecem reconhecimento e registro nos léxicos.","E":"Não se formula um novo conjunto de regras obrigatórias."},"takeaway":"Dicionários registram práticas da comunidade; não são a origem única das palavras.","key":"linguagens:L226","area":"linguagens","year":2021,"number":7,"answer":"D","subject":"Variação linguística","topic":"Oralidade, registros e adequação comunicativa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[6],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A comparação ressalta a dimensão da conquista","steps":["O prêmio reúne trabalhos em circuito internacional.","A fala destaca que aquele era o único finalista fora do eixo citado.","C acentua a proeza da premiação de uma história do interior nordestino."],"alternatives":{"A":"A criação do museu é relevante, mas não é o foco específico da comparação entre finalistas.","B":"Havia concorrentes; a frase destaca a origem distinta de uma produção.","C":"A singularidade no conjunto reforça a importância do reconhecimento conquistado.","D":"Não se oferecem dados de investimento que sustentem essa conclusão.","E":"A parceria é informada, mas a citação destaca o lugar da obra na competição."},"takeaway":"Pergunte qual informação uma citação torna mais forte no argumento, não apenas o que ela menciona.","key":"linguagens:L150","area":"linguagens","year":2021,"number":8,"answer":"C","subject":"Interpretação de texto e gêneros textuais","topic":"Intertextualidade e relações entre textos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[7],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Os ditados preservam saberes coletivos","steps":["As personagens interpretam sorte e trabalho com expressões proverbiais.","A fórmula sobre vacas e bois mobiliza memória compartilhada.","D identifica o valor patrimonial dos ditados, não sua verdade literal."],"alternatives":{"A":"As enfermidades não são o principal recurso de memória coletiva.","B":"O trecho não prova que as ocupações citadas tenham desaparecido.","C":"Nomes podem caracterizar, mas não são o patrimônio linguístico destacado.","D":"Os provérbios condensam experiências e avaliações transmitidas socialmente.","E":"O efeito não é demonstrar que crenças populares sejam falsas."},"takeaway":"Em patrimônio linguístico, observe fórmulas expressivas que circulam entre gerações.","key":"linguagens:L342","area":"linguagens","year":2021,"number":9,"answer":"D","subject":"Gramática a serviço do sentido","topic":"Classes de palavras, referenciação e efeitos de sentido","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[7],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A avaliação do Oscar contém uma crítica indireta","steps":["As primeiras opções informam prêmio, personagem ou procedimento de câmera.","Em E, chamar uma premiação de passo à frente avalia positivamente a obra.","A formulação também pressupõe limites nas escolhas anteriores dos votantes: opinião implícita."],"alternatives":{"A":"A referência ao prêmio de Cannes apresenta uma informação verificável.","B":"A função da personagem é informação do enredo.","C":"O posicionamento da câmera é descrito como procedimento do filme.","D":"A procura do rabino relata uma ação narrativa.","E":"Passo à frente sugere que reconhecer a ousadia superaria padrões anteriores da Academia."},"takeaway":"Uma opinião pode vir por pressuposto e comparação, sem a expressão eu acho.","key":"linguagens:L097","area":"linguagens","year":2021,"number":10,"answer":"E","subject":"Interpretação de texto e gêneros textuais","topic":"Argumentação e pontos de vista","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[8],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A língua registra relações de violência escravista","steps":["As formas de tratamento marcam a hierarquia entre senhor e escravizado.","O corpo ameaçado e a imposição religiosa revelam violência física e simbólica.","A é a síntese que integra vocabulário e situação."],"alternatives":{"A":"Tronco, mutilação e formas de tratamento explicitam subordinação e violência.","B":"A cultura africana aparece, mas não esgota o sofrimento e a hierarquia narrados.","C":"A coexistência religiosa não é relativizada como tema central.","D":"Não se narra uma relação amorosa consensual entre classes.","E":"Diferentes visões existem, mas a alternativa é genérica diante da violência diretamente mostrada."},"takeaway":"Formas linguísticas podem funcionar como marcas de poder e memória histórica.","key":"linguagens:L268","area":"linguagens","year":2021,"number":11,"answer":"A","subject":"Variação linguística","topic":"História da língua e diversidade cultural","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[8],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Pet tem dois sentidos para recusar o abandono","steps":["A garrafa representa o plástico PET, e o cão, o animal de estimação.","A campanha aplica descartável só ao primeiro referente.","D interpreta a associação como sensibilização contra tratar o animal como objeto descartável."],"alternatives":{"A":"Não se apresenta um canal ou instrução central de denúncia.","B":"O abandono é ligado à negligência, não separado dela.","C":"A mensagem não convida explicitamente a adotar um animal.","D":"O jogo verbal e visual questiona a atitude de abandonar um ser vivo.","E":"A lei reforça a mensagem, mas o recurso principal não detalha penas."},"takeaway":"Imagem e polissemia podem construir uma oposição ética, não apenas um trocadilho.","key":"linguagens:L006","area":"linguagens","year":2021,"number":12,"answer":"D","subject":"Interpretação de texto e gêneros textuais","topic":"Recursos expressivos e construção de sentidos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A igualdade prometida contrasta com as renúncias da mãe","steps":["A personagem enumera prazeres e vida social abandonados.","O último quadro chama isso de capítulo da emancipação feminina.","C identifica ironia diante de condições desiguais, sem condenar a maternidade em si."],"alternatives":{"A":"A tira não faz uma convocação direta à luta por direitos civis.","B":"A lista de renúncias não comprova autonomia plenamente conquistada.","C":"A expressão emancipação contrasta com sacrifícios concentrados na mulher.","D":"Abandonar a vida social é mostrado criticamente, não recomendado.","E":"O alvo é a desigualdade das condições, não a existência da maternidade."},"takeaway":"Ironia exige comparar a afirmação final com a situação construída nos quadros.","key":"linguagens:L055","area":"linguagens","year":2021,"number":13,"answer":"C","subject":"Interpretação de texto e gêneros textuais","topic":"Gêneros textuais e finalidades comunicativas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A arte mantém visível uma crise humana","steps":["A reportagem apresenta esculturas que evocam refugiados numa balsa.","Seu destaque vai além de localização e novidade do museu.","E reconhece a arte como memória de episódios que não devem se repetir."],"alternatives":{"A":"Turismo e localização são contexto, não a função paralela principal.","B":"O texto se refere a uma crise específica, não a todas as travessias ao longo dos séculos.","C":"A inovação técnica é informada, mas não explica o apelo humanitário.","D":"Não se afirma que todo o museu foi construído exclusivamente como memorial de mortos.","E":"As expressões de abandono tornam a crise perceptível e preservam sua lembrança."},"takeaway":"Uma reportagem cultural pode mobilizar memória e consciência social por meio da obra apresentada.","key":"linguagens:L007","area":"linguagens","year":2021,"number":14,"answer":"E","subject":"Interpretação de texto e gêneros textuais","topic":"Recursos expressivos e construção de sentidos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Pestana cria o popular enquanto deseja consagração erudita","steps":["O músico produz polcas espontaneamente, com vitalidade.","Deseja, porém, a imortalidade associada aos mestres clássicos.","D identifica tensão entre erudito e popular na formação musical brasileira."],"alternatives":{"A":"Não é demonstrada uma inferioridade técnica necessária do popular.","B":"O fragmento não mede a prevalência de referências africanas em toda a população.","C":"Pestana já é célebre; a questão não é ausência absoluta de prestígio das danças.","D":"O desejo erudito e a criação popular entram em conflito no mesmo compositor.","E":"A importância do clássico é apenas um polo; falta o conflito com a produção popular."},"takeaway":"Não transforme uma hierarquia social de prestígio em prova de superioridade artística intrínseca.","key":"linguagens:L589","area":"linguagens","year":2021,"number":15,"answer":"D","subject":"Artes","topic":"Dança e expressão corporal","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[10],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A canção dá forma concreta à pressa criticada","steps":["O artigo critica comunicação apressada e superficial.","O encontro no sinal apresenta personagens que adiam a conversa.","B identifica exemplificação concreta da tese, antes da proposta de desacelerar."],"alternatives":{"A":"A canção não funciona principalmente como advertência explícita de risco.","B":"As falas apressadas encenam uma situação que torna a crítica reconhecível.","C":"A letra citada mostra a correria, não uma situação serena em contraponto.","D":"Não se questiona a veracidade de um clichê como objetivo central da citação.","E":"A solução slow life aparece depois; a canção exemplifica o problema."},"takeaway":"Diferencie função do exemplo e função da conclusão dentro de um argumento.","key":"linguagens:L151","area":"linguagens","year":2021,"number":16,"answer":"B","subject":"Interpretação de texto e gêneros textuais","topic":"Intertextualidade e relações entre textos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[10],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Denunciar o racismo rompe o silêncio oficial","steps":["O texto contrasta culpabilização de jogadores com a reação de Paulo César.","Ele nomeia publicamente o racismo que o discurso oficial silenciava.","E identifica a atitude contestadora que enfraquece o mito."],"alternatives":{"A":"A culpabilização de 1950 mostra racismo, mas não é a reação contestadora destacada.","B":"A projeção mundial não desmonta sozinha a ideia de harmonia racial.","C":"Depreciar o esporte não equivale a denunciar a discriminação racial.","D":"Interditar a palavra ajuda a sustentar o mito, e não a enfraquecê-lo.","E":"O jogador recusa o papel esperado e torna explícita a discriminação."},"takeaway":"Presença de atletas negros e sucesso esportivo não demonstram ausência de racismo.","key":"linguagens:L660","area":"linguagens","year":2021,"number":17,"answer":"E","subject":"Educação Física","topic":"Esporte, inclusão e práticas corporais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[11],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Moema é construída como figura dramática e idealizada","steps":["A tela mostra o corpo indígena em composição cuidadosamente encenada.","A morte é tratada por idealização da beleza e dramaticidade indianista.","D associa o tratamento visual à estética romântica, não a retrato documental."],"alternatives":{"A":"A idealização não é registro fiel de uma pessoa real.","B":"Morte é um tema amplo, presente em muitas estéticas.","C":"Dialogar com literatura não basta para definir o tratamento romântico.","D":"A construção dramática e idealizada da personagem indígena traduz o indianismo.","E":"A natureza compõe a cena, mas não há oposição simples entre humanidade e natureza."},"takeaway":"Na análise de estilo, diferencie tema e modo de representar.","key":"linguagens:L625","area":"linguagens","year":2021,"number":18,"answer":"D","subject":"Artes","topic":"História da arte e outras manifestações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[11],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Menos brincadeira coletiva, menos experiência corporal ativa","steps":["O texto aponta menos tempo livre e mais tarefas.","O brincar migra para aparelhos eletrônicos, em casa e muitas vezes a sós.","D identifica vivência corporal menos ativa nesse cenário, sem generalizar a todos os jogos digitais."],"alternatives":{"A":"O estudo descreve redução, não aumento, da convivência lúdica.","B":"As crianças têm menos oportunidade de lazer, não maior difusão.","C":"Não se apresenta criação de espaços externos para brincar.","D":"A substituição descrita reduz movimento e exploração corporal no lazer.","E":"O tempo para brincar diminuiu na comparação apresentada."},"takeaway":"Leia a tendência do estudo sem tratá-la como regra absoluta sobre cada criança.","key":"linguagens:L702","area":"linguagens","year":2021,"number":19,"answer":"D","subject":"Educação Física","topic":"Cultura corporal, jogos e lazer","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[11],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A dança se transforma no encontro entre mídias","steps":["O projeto combina corpo, vídeo, computação e rede.","A concepção considera condições próprias de circulação na internet.","D identifica expressão multimodal, não simples troca de palco por uma animação."],"alternatives":{"A":"O texto não estabelece oposição conceitual a todo grande espetáculo.","B":"Financiamento não é a inovação descrita.","C":"O corpo não é necessariamente eliminado ou substituído por movimento computacional.","D":"O cruzamento de linguagens abre novas possibilidades estéticas e de acesso.","E":"Limites técnicos são considerados, mas não se descreve personalização para cada perfil."},"takeaway":"Multimodalidade articula recursos: o resultado não é a soma neutra de suportes isolados.","key":"linguagens:L734","area":"linguagens","year":2021,"number":20,"answer":"D","subject":"Tecnologias da Informação e Comunicação","topic":"Cultura digital, redes e gêneros digitais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[12],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Divergem sobre a manutenção dos estoques","steps":["I apresenta reposição contínua pelo ciclo hidrológico.","II ressalta a barreira à infiltração e à recuperação de aquíferos.","A identifica divergência sobre manter estoques, não sobre a existência de evaporação."],"alternatives":{"A":"I enfatiza reposição, enquanto II problematiza a recuperação de reservas subterrâneas.","B":"II admite o consumo superficial; isso não é o contraste entre ambos.","C":"O texto II não discute especificamente recuperação de regiões áridas.","D":"Nenhum texto propõe reduzir essas taxas para resolver o problema.","E":"I reconhece distribuição desigual, e II não promete equalizá-la."},"takeaway":"Compare as teses sobre um mesmo objeto, sem atribuir aos textos propostas que não fazem.","key":"linguagens:L152","area":"linguagens","year":2021,"number":21,"answer":"A","subject":"Interpretação de texto e gêneros textuais","topic":"Intertextualidade e relações entre textos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[12],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Tu e você revelam diversidade histórica e regional","steps":["O texto compara épocas e diferentes cidades.","A idade aparece num caso individual, não como regra única.","B reúne a variação observada sem apagar diferenças de registro."],"alternatives":{"A":"Um professor idoso recebe você; a idade não determina sozinha a escolha.","B":"A coexistência dos pronomes evidencia a diversidade dos usos da língua.","C":"Tu não é apresentado como tratamento usado uniformemente no país.","D":"Variação não implica inexistência de diferenças de formalidade.","E":"Cartas antigas e usos atuais mostram mudança, não imobilidade."},"takeaway":"Variação pode envolver simultaneamente região, época e situação comunicativa.","key":"linguagens:L227","area":"linguagens","year":2021,"number":22,"answer":"B","subject":"Variação linguística","topic":"Oralidade, registros e adequação comunicativa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O encontro entre repertórios permite recriação","steps":["John Lennon da Silva retoma uma obra de balé.","Ele a interpreta com popping e outro figurino.","B valoriza encontro criativo entre experiências socioculturais distintas."],"alternatives":{"A":"O figurino compõe a mudança, mas não é indicado como sua causa única.","B":"Balé e dança de rua entram em diálogo sem exigência de hierarquia.","C":"A diferença entre linguagens não prova superioridade de uma delas.","D":"O artista conhece e reinterpreta obra de tradição erudita.","E":"A questão não atribui a inovação prioritariamente ao gênero do intérprete."},"takeaway":"Releitura não é cópia defeituosa: pode construir novo sentido a partir de um repertório anterior.","key":"linguagens:L590","area":"linguagens","year":2021,"number":23,"answer":"B","subject":"Artes","topic":"Dança e expressão corporal","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A violência normalizada suspende garantias humanas","steps":["A sequência acumula agressões e lesões do preso.","Frases breves e repetição de apanhar evidenciam obediência produzida pela violência.","B identifica atitudes próprias de exceção, com direitos sistematicamente violados."],"alternatives":{"A":"O texto expõe criticamente a brutalidade, sem simplesmente reiterar o senso comum.","B":"Espancamentos arbitrários e risco de morte tornam visível a suspensão prática de garantias.","C":"O preso é representado, mas não se estabelece interlocução direta com grupos.","D":"A empatia pode ser efeito, mas o núcleo é a representação da violência institucional.","E":"A brutalidade não é um acontecimento impossível usado como absurdo fantástico."},"takeaway":"Estado de exceção pode ser identificado pela normalização de atos fora das garantias jurídicas.","key":"linguagens:L374","area":"linguagens","year":2021,"number":24,"answer":"B","subject":"Literatura","topic":"Literatura contemporânea (pós-1960)","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A autoridade se curva a outra autoridade","steps":["O delegado intimida a família em nome do general.","A mulher invoca parentes militares de patente alta.","B identifica efeito anedótico: a inversão faz o intimidador engolir em seco."],"alternatives":{"A":"A xenofobia existe, mas não explica sozinha a virada humorística final.","B":"A pergunta sobre ser da ativa revela sua submissão oportunista à hierarquia.","C":"O narrador não oculta sua perspectiva com esse recurso.","D":"A hostilidade é parte da cena, mas a mudança inesperada produz humor.","E":"O conto expõe criticamente esse poder, não o elogia."},"takeaway":"Na anedota, procure a reversão que reorganiza o sentido das falas anteriores.","key":"linguagens:L375","area":"linguagens","year":2021,"number":25,"answer":"B","subject":"Literatura","topic":"Literatura contemporânea (pós-1960)","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A retomada esclarece quem é o gigante","steps":["O verso chama Pedro de gigante do Brasil.","O parágrafo seguinte retoma O Pedro mencionado.","D conecta as expressões ao mesmo referente, Dom Pedro II."],"alternatives":{"A":"É assim retoma uma situação ou modo de descobrir, não apenas os papéis.","B":"Sobre o qual se liga a nome antigo, não a algo novo.","C":"Por exemplo introduz um caso e não renomeia um nome antigo.","D":"O Pedro mencionado recupera o Pedro do verso, identificado como gigante do Brasil.","E":"O imperador e o bruxo são pessoas diferentes: Pedro II e Machado."},"takeaway":"Referenciação exige verificar identidade de referente, não mera proximidade entre expressões.","key":"linguagens:L343","area":"linguagens","year":2021,"number":26,"answer":"D","subject":"Gramática a serviço do sentido","topic":"Classes de palavras, referenciação e efeitos de sentido","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O desenho moderno reduz o rebuscamento","steps":["A reportagem contrapõe gosto colonial e mobiliário contemporâneo.","Linhas retas, curvas suaves e materiais formam composições mais simples.","E abrange a simplificação visual, sem reduzi-la a um traço isolado."],"alternatives":{"A":"Há linhas retas e curvas: somente retas é uma redução indevida.","B":"O gosto rebuscado é justamente o que os designers abandonam.","C":"Assimetria não é estabelecida como característica decisiva da série.","D":"O texto cita diferentes madeiras e revestimentos, não matéria-prima única.","E":"O conjunto retira excessos ornamentais e organiza informações visuais de modo sintético."},"takeaway":"Uma síntese estética precisa abranger o conjunto, não apenas um material ou uma linha.","key":"linguagens:L569","area":"linguagens","year":2021,"number":27,"answer":"E","subject":"Artes","topic":"Arte contemporânea e linguagens visuais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A rede adapta sua estrutura ao uso","steps":["O texto apresenta usuários já concentrados nos grupos.","A mudança de design privilegia essa prática de comunidades.","B identifica assimilação do comportamento dos usuários pela plataforma."],"alternatives":{"A":"A privacidade é promessa pouco detalhada, não o resultado demonstrado da mudança.","B":"O novo destaque dado a grupos responde a práticas que já mobilizavam os usuários.","C":"Interação é ampla demais: o texto mostra adaptação a um padrão específico de uso.","D":"Monetização é possibilidade futura, não explicação única de toda evolução das TICs.","E":"A referência ao Orkut não prova que toda tecnologia evolua para imitar outra."},"takeaway":"Relacione mudança técnica e prática social sem tomar promessa comercial por resultado comprovado.","key":"linguagens:L735","area":"linguagens","year":2021,"number":28,"answer":"B","subject":"Tecnologias da Informação e Comunicação","topic":"Cultura digital, redes e gêneros digitais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A dúvida deve levar à investigação","steps":["O autor recusa a ideia de isenção absoluta.","Distingue desconfiar passivamente de examinar versões e elementos ocultos.","C resume a postura crítica e ativa defendida."],"alternatives":{"A":"Nenhuma fonte é apresentada como garantia absoluta de verdade.","B":"A circulação ampla de um jornal não assegura leitura crítica.","C":"Comparar perspectivas e investigar permite avaliar informações recebidas.","D":"O alvo é a leitura atual, não apenas condenar o jornalismo anterior.","E":"O texto nega imparcialidade absoluta, em vez de fazer dela um critério garantido."},"takeaway":"Leitura crítica não é descrença automática: exige busca de evidências e comparação.","key":"linguagens:L098","area":"linguagens","year":2021,"number":29,"answer":"C","subject":"Interpretação de texto e gêneros textuais","topic":"Argumentação e pontos de vista","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[15],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O purismo ignora a situação de conversa","steps":["Pelino interrompe falas informais para impor suas correções.","A posição não distingue conversa cotidiana e escrita monitorada.","E identifica desconsideração da variação de formalidade."],"alternatives":{"A":"Pelino privilegia a regra; não contesta seu ensino em nome do conteúdo.","B":"Há purismo, mas a justificativa patriótica não é demonstrada no trecho.","C":"Ele intervém em qualquer pequena incorreção, sem complacência.","D":"O personagem defende preceitos normativos; não os invalida.","E":"Aplicar a mesma vigilância a toda conversa apaga diferenças entre situações."},"takeaway":"Adequação não é abandonar a norma-padrão: é considerar gênero, objetivo e contexto.","key":"linguagens:L228","area":"linguagens","year":2021,"number":30,"answer":"E","subject":"Variação linguística","topic":"Oralidade, registros e adequação comunicativa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[15],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A inovação técnica amplia acesso e possibilidades","steps":["O skate surge adaptando materiais do patins.","O uretano oferece aderência, novas manobras e entrada de inexperientes.","A interpreta o processo como ampliação da participação."],"alternatives":{"A":"Materiais e condições mais favoráveis ajudam mais pessoas a praticar.","B":"O comércio é um desdobramento, não o único aspecto da história.","C":"Não se acompanha a trajetória de um atleta profissional específico.","D":"Surgir na falta de ondas não significa substituir socialmente o surfe.","E":"A dependência de novos materiais contradiz uma autonomia técnica absoluta."},"takeaway":"Democratização de uma prática pode envolver condições materiais que reduzem barreiras de acesso.","key":"linguagens:L703","area":"linguagens","year":2021,"number":31,"answer":"A","subject":"Educação Física","topic":"Cultura corporal, jogos e lazer","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[16],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A memória afetiva centra o enunciador","steps":["O narrador contrapõe cheiro do estojo e do notebook.","Avaliações como gostoso e abominável registram sua experiência.","D identifica função emotiva, centrada na atitude do eu."],"alternatives":{"A":"Há elaboração literária, mas o foco solicitado são juízos e sensações pessoais.","B":"O tema não é explicar o funcionamento do próprio código linguístico.","C":"Dados objetivos não comandam a narrativa afetiva.","D":"Primeira pessoa, lembranças e avaliações expressam a relação do narrador com o vivido.","E":"Não predominam ordens destinadas a orientar o leitor."},"takeaway":"Textos podem reunir funções; predominância depende das marcas e da finalidade central.","key":"linguagens:L290","area":"linguagens","year":2021,"number":32,"answer":"D","subject":"Funções e figuras de linguagem","topic":"Funções da linguagem","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[16],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O prefácio apresenta o percurso e convida à leitura","steps":["Os quadrinhos mostram pesquisa, roteiro e produção do livro.","O fechamento afirma que falta ser lido.","A identifica a função de apresentar a obra, comum ao prefácio."],"alternatives":{"A":"Apresentar a obra e preparar o leitor define sua função prefacial.","B":"Imagens e emoção também existem em outros gêneros.","C":"Descrever o processo ajuda a apresentação, mas não define sozinho o gênero.","D":"A combinação manual e digital é conteúdo, não a finalidade comunicativa.","E":"Recursos gráficos não bastam para distinguir prefácio de outros quadrinhos."},"takeaway":"Gênero se reconhece também pela função no contexto em que o texto circula.","key":"linguagens:L736","area":"linguagens","year":2021,"number":33,"answer":"A","subject":"Tecnologias da Informação e Comunicação","topic":"Cultura digital, redes e gêneros digitais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[16],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O alerta pretende mudar o hábito noturno","steps":["O infográfico reúne riscos do celular antes de dormir.","Inclui orientações sobre evitar telas e preservar o sono.","B interpreta a combinação como persuasão para modificar hábitos prejudiciais."],"alternatives":{"A":"Informar riscos é um meio; o propósito ultrapassa divulgar dados científicos.","B":"Alertas visuais e recomendações buscam mudança de conduta de responsáveis e crianças.","C":"O foco é sono e exposição a telas, não apenas falta de exercício.","D":"Não se procura extinguir todo uso de telefone pelo público infantil.","E":"A substituição por atividades lúdicas não é a recomendação central apresentada."},"takeaway":"Em campanhas, diferencie informação de apoio e comportamento que se quer estimular.","key":"linguagens:L056","area":"linguagens","year":2021,"number":34,"answer":"B","subject":"Interpretação de texto e gêneros textuais","topic":"Gêneros textuais e finalidades comunicativas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[17],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O olhar masculino define o lugar social da mulher","steps":["Os homens classificam idade, aparência, estado civil e profissão.","A mulher é objeto dessa avaliação, sem tomar a palavra.","D identifica identidade referendada por categorias e juízos masculinos."],"alternatives":{"A":"A esmola inicia a observação, mas não garante dignificação perante os homens.","B":"Os personagens não demonstram causalmente que o estilo de vida preserve a juventude.","C":"Não se conhece seu bem-estar nem uma dependência necessária de casamento.","D":"A descrição a situa socialmente segundo um julgamento exercido por homens.","E":"Há exclusão de profissões na inferência, não relato de renúncia pessoal ao trabalho."},"takeaway":"A questão pede a visão das personagens; não a confunda com uma verdade defendida pelo texto.","key":"linguagens:L460","area":"linguagens","year":2021,"number":35,"answer":"D","subject":"Literatura","topic":"Realismo e Naturalismo — Machado de Assis e outros","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[17],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O recipiente deixa de ser utilitário e vira máscara","steps":["O artista usa plástico descartado e tecido.","A obra explora formas humanas, mas não se destina ao uso ritual da máscara.","B identifica mudança de função e novo posicionamento estético do objeto."],"alternatives":{"A":"Combinar materiais não implica empobrecimento artístico.","B":"O lixo é ressignificado como objeto artístico e crítico.","C":"Não há instrução de participação para completar uma obra inacabada.","D":"Existe crítica ao consumo, mas a alternativa reduz a obra a militância ecológica continental.","E":"Usar refugo é escolha expressiva, não prova de falta de recursos do artista."},"takeaway":"A matéria-prima não determina o valor da obra; observe a transformação de função e sentido.","key":"linguagens:L591","area":"linguagens","year":2021,"number":36,"answer":"B","subject":"Artes","topic":"Dança e expressão corporal","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[18],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"As ordens obedientes são ironizadas","steps":["A voz manda parecer alegre mesmo desempregado.","As recompensas absurdas contrastam com submissão e silenciamento.","A identifica crítica ao conformismo, não uma recomendação literal."],"alternatives":{"A":"O elogio aparente da disciplina denuncia a aceitação passiva de injustiças.","B":"Ler as ordens literalmente apaga a ironia construída pelas contradições.","C":"A religião participa das imagens irônicas, não oferece a solução efetiva.","D":"Carnaval e samba aparecem, mas a crítica não é condenação das festas em si.","E":"A canção questiona a indiferença, em vez de defendê-la."},"takeaway":"Ironia pode usar o discurso que critica para expor suas contradições.","key":"linguagens:L099","area":"linguagens","year":2021,"number":37,"answer":"A","subject":"Interpretação de texto e gêneros textuais","topic":"Argumentação e pontos de vista","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[18],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A memória desenha o reencontro desejado","steps":["O eu lírico pede notícias que permitam aproximar-se do outro.","Recordações de luz, marés e pés molhados alimentam a expectativa.","C identifica desejo de realização amorosa projetado pela memória."],"alternatives":{"A":"O reencontro é desejado e imaginado, não descartado por ceticismo.","B":"A monotonia é atribuída como hipótese à experiência do outro.","C":"O passado recordado compõe a possibilidade de uma plenitude futura.","D":"Não há acusação central contra a pessoa distante.","E":"O poema deseja proximidade, em vez de formular uma discussão conceitual do amor."},"takeaway":"Diferencie lembrança, condição imaginada e desejo no movimento do poema.","key":"linguagens:L376","area":"linguagens","year":2021,"number":38,"answer":"C","subject":"Literatura","topic":"Literatura contemporânea (pós-1960)","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[18],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A oralidade aparece no vocabulário e na contração","steps":["Falação é escolha expressiva coloquial.","Pros contrai para os em registro informal.","A reúne duas marcas claras de uso cotidiano."],"alternatives":{"A":"Falação e pros bailes são escolhas características de registro informal.","B":"Você isoladamente não basta, e teatro de revista nomeia um gênero artístico.","C":"As palavras perfeito e Carnaval não são marcas específicas de informalidade.","D":"Oculista é vocabulário corrente, sem contração ou marca coloquial distintiva.","E":"Curar e falso moralista não exemplificam por si o registro informal."},"takeaway":"Uma palavra comum não é automaticamente informal; procure traços efetivos de registro.","key":"linguagens:L229","area":"linguagens","year":2021,"number":39,"answer":"A","subject":"Variação linguística","topic":"Oralidade, registros e adequação comunicativa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[19],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O afeto lírico humaniza a mulher segregada","steps":["O relato expõe abandono e violência institucional.","O narrador transforma grades e hospital em imagens de palácio, princesa e lanças.","C reconhece imersão lírica que restitui singularidade e possibilidade de amor."],"alternatives":{"A":"O amor declarado não é ironia contra a mulher ou sua família.","B":"A violência é denunciada, não aceita resignadamente como terapia.","C":"As metáforas e a proximidade afetiva atravessam o espaço de segregação.","D":"Não se investiga cientificamente a mente, mas a experiência e o olhar do narrador.","E":"A linguagem metafórica não é um programa clínico de recuperação da lucidez."},"takeaway":"Lirismo pode ressignificar uma realidade brutal sem negar a violência que a constitui.","key":"linguagens:L377","area":"linguagens","year":2021,"number":40,"answer":"C","subject":"Literatura","topic":"Literatura contemporânea (pós-1960)","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[19],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O pavão vermelho materializa a alegria conquistada","steps":["O primeiro verso identifica a alegria com o pavão.","O vermelho radiante supera os pavões anteriores.","D interpreta a imagem como realização plena do eu lírico."],"alternatives":{"A":"O quintal localiza a experiência, mas não expressa um programa de isolamento.","B":"A natureza é veículo da imagem, não seu sentido principal.","C":"Há sinestesia em cor sonora, mas o conjunto metaforiza a alegria conquistada.","D":"O pavão atual substitui os anteriores como imagem de plenitude afetiva.","E":"Luz e aurora não bastam para caracterizar uma visão religiosa ou mística."},"takeaway":"Não escolha um recurso isolado quando o comando pede o sentido global da imagem.","key":"linguagens:L416","area":"linguagens","year":2021,"number":41,"answer":"D","subject":"Literatura","topic":"Modernismo: primeira geração","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[19],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O corpo também é educado socialmente","steps":["O comando parte da reinvenção social do corpo.","Erotização envolve gestos, desejos e modos de agir aprendidos.","C identifica esse processo cultural, mais amplo que intervenções físicas pontuais."],"alternatives":{"A":"Exercício pode modificar o corpo, mas não explica toda construção de sentidos eróticos.","B":"Produtos estéticos são um recurso possível, não o fundamento amplo do processo.","C":"Normas culturais ensinam como mover-se, apresentar-se e ser percebido.","D":"Espaços de prática não explicam sozinhos a atribuição social de sensualidade.","E":"Vivências de lazer não correspondem necessariamente à erotização do corpo."},"takeaway":"A representação do corpo depende de valores históricos, não só de características biológicas.","key":"linguagens:L704","area":"linguagens","year":2021,"number":42,"answer":"C","subject":"Educação Física","topic":"Cultura corporal, jogos e lazer","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[19],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A ancestralidade sustenta a resistência à escravidão","steps":["As falas evocam tata, calunga e a outra terra.","As marcas de violência contrastam com afeto e memória compartilhada.","D reconhece resistência identitária, sem confundir a cena com uma vitória material já alcançada."],"alternatives":{"A":"O projeto de permanecerem juntos evidencia afeto, não sua impossibilidade absoluta.","B":"As marcas do corpo mostram violência, mas não integram sozinhas o lirismo e as referências culturais.","C":"Há sofrimento, porém a memória e o projeto de união ultrapassam abatimento passivo.","D":"Vocabulário, ancestralidade e vínculo afetivo resistem à desumanização colonial.","E":"As referências ancestrais permanecem presentes, apesar do exílio imposto."},"takeaway":"Leia palavras, corpos e sequência: resistência também pode ocorrer pela preservação de vínculos e sentidos.","key":"linguagens:L626","area":"linguagens","year":2021,"number":43,"answer":"D","subject":"Artes","topic":"História da arte e outras manifestações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[20],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A confiança no meio não garante a verdade","steps":["O vereador contrata divulgação frequente de um talento inexistente.","Pessoas afirmam ter visto o que a narrativa declara falso.","D identifica circulação de informação não fidedigna apoiada na confiança no sistema."],"alternatives":{"A":"Pode haver interesse político, mas a ironia recai na falsa reputação difundida.","B":"Anúncios são citados, porém não explicam o exemplo de testemunhos falsos.","C":"Apelo popular é insuficiente para caracterizar a falsidade do relato.","D":"A repetição e a credibilidade do meio fazem uma invenção parecer evidência.","E":"Utilidade pública não descreve a suposta habilidade inventada do vereador."},"takeaway":"Popularidade, repetição e confiança no canal não substituem verificação da informação.","key":"linguagens:L796","area":"linguagens","year":2021,"number":44,"answer":"D","subject":"Tecnologias da Informação e Comunicação","topic":"Leitura crítica da mídia e circulação da informação","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[20],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A trajetória do músico valoriza a riqueza do choro","steps":["O texto destaca a singularidade musical e a importância de Abel Ferreira.","Também mostra permanência do gênero apesar da pouca divulgação.","C sintetiza a valorização histórica e estética que organiza os exemplos."],"alternatives":{"A":"A escola é citada numa avaliação, mas não explica isoladamente desconhecimento de toda a obra.","B":"O acervo merece cuidado, porém o artigo não se reduz a reivindicar verbas estatais.","C":"Biografia, elogios e resistência cultural convergem para reconhecer o valor do gênero.","D":"Os dados biográficos servem à valorização do choro, não são finalidade única.","E":"As dificuldades de circulação não anulam a vivacidade afirmada no início."},"takeaway":"Identifique a finalidade que integra exemplos, avaliações e informações, não só um detalhe do texto.","key":"linguagens:L100","area":"linguagens","year":2021,"number":45,"answer":"C","subject":"Interpretação de texto e gêneros textuais","topic":"Argumentação e pontos de vista","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2021_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2021.pdf","sha256":"b9d1a2cca6ba38dbac52e437371af2557173d38bfe0d0cbc948b1060547eead4","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2021.pdf","sourceExamPages":[20],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}}];
